import{_ as s,a as n}from"./chunks/fs25-1.Bk5zTnDc.js";import{_ as e,a as t,b as l,c as i}from"./chunks/fs62-1.Bm5-9Q4-.js";import{_ as r,a as p}from"./chunks/fs50-1.CFxer_h3.js";import{_ as o,o as c,c as d,a4 as h}from"./chunks/framework.B0hSrcZ6.js";const g="/info/14-engineering-s1.webp",u="/info/14-engineering-s3.webp",k="/info/14-engineering-s4.webp",R=JSON.parse('{"title":"第 14 章 案例：工程与研发团队","description":"本章展示研发团队借助 Grok Bot 实现云端托管的工程实践。通过状态机编排多智能体，落地代码巡检与仓库值班台，让开发者摆脱本地盯梢并自主把关交付成果。","frontmatter":{},"headers":[],"relativePath":"part2/14-engineering.md","filePath":"part2/14-engineering.md","lastUpdated":1792210948000}'),f={name:"part2/14-engineering.md"};function b(m,a,x,y,B,C){return c(),d("div",null,[...a[0]||(a[0]=[h('<h1 id="第-14-章-案例-工程与研发团队" tabindex="-1">第 14 章 案例：工程与研发团队 <a class="header-anchor" href="#第-14-章-案例-工程与研发团队" aria-label="Permalink to &quot;第 14 章 案例：工程与研发团队&quot;">​</a></h1><p>别在本地盯梢，把活<strong>托管到云端</strong>。</p><ul><li>电脑随时关机，24 小时运转，免得凌晨两点爬起来查 CI。</li><li>隔离环境编码，合并请求附真实证据与日志，防断言改绿。</li></ul><p>早晨<strong>看交付报告把关发布</strong>。</p><h2 id="核心架构-harness、模型大脑与本地-cli-agent-分工" tabindex="-1">核心架构：Harness、模型大脑与本地 CLI Agent 分工 <a class="header-anchor" href="#核心架构-harness、模型大脑与本地-cli-agent-分工" aria-label="Permalink to &quot;核心架构：Harness、模型大脑与本地 CLI Agent 分工&quot;">​</a></h2><p><img src="'+g+`" alt="核心架构：Harness、模型大脑与本地 CLI Agent 分工" width="1600" height="1013" decoding="async"></p><h3 id="角色定位与三方分工" tabindex="-1">角色定位与三方分工 <a class="header-anchor" href="#角色定位与三方分工" aria-label="Permalink to &quot;角色定位与三方分工&quot;">​</a></h3><p>2026 年 10 月 7 日平台引入了 Claude Opus 5.5 等模型参与推理。<strong>系统自动调度模型，不提供手动单次选择器</strong>。别指望单一模型特性，流程要靠状态文件和自动化校验卡死。</p><table tabindex="0"><thead><tr><th style="text-align:left;">角色</th><th style="text-align:left;">运行宿主</th><th style="text-align:left;">权限与职责</th></tr></thead><tbody><tr><td style="text-align:left;">Grok Bot</td><td style="text-align:left;">云端电脑（<code>/workspace</code> 共享存储）</td><td style="text-align:left;">跑巡检与派发任务，<strong>只生成 Draft PR，严禁直接推默认分支或上线</strong></td></tr><tr><td style="text-align:left;">本地 CLI Agent</td><td style="text-align:left;">本地终端或临时容器</td><td style="text-align:left;">独立分支拉依赖改代码，跑构建</td></tr><tr><td style="text-align:left;">人类主管</td><td style="text-align:left;">个人工作站</td><td style="text-align:left;"><strong>手握发布密钥与生产写权限</strong>，负责架构决策与审批合并</td></tr></tbody></table><h3 id="环境配置与安全隔离" tabindex="-1">环境配置与安全隔离 <a class="header-anchor" href="#环境配置与安全隔离" aria-label="Permalink to &quot;环境配置与安全隔离&quot;">​</a></h3><p>同账号下所有 Bot 共享同一台云电脑、命令行凭据与浏览器会话，<strong>给 Bot 改名起不到权限隔离的作用</strong>。遇到敏感登录别在对话框贴明文，<strong>必须用 Take Control 在远程屏幕人工认证</strong>，把会话留给浏览器。</p><h3 id="运行环境自检与持久化" tabindex="-1">运行环境自检与持久化 <a class="header-anchor" href="#运行环境自检与持久化" aria-label="Permalink to &quot;运行环境自检与持久化&quot;">​</a></h3><p>接入新仓库前，先在 Grok Bot 跑自检命令摸清配置。</p><details class="details custom-block"><summary>运行环境自检与持久化</summary><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;CPU 核心数:&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nproc</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;内存分配:&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">free</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;工作区磁盘空间:&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">df</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /workspace</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;系统版本与 Git:&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/os-release</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div></details><p>更新时系统依赖可能被重置，只有 <code>/workspace</code> 目录会持久保留。<strong>所有核心状态都要用 Git 同步到远端或存进结构化文件</strong>。</p><p>参考文档包括 <a href="https://cursor.com/cn/docs/grok-bot/work" target="_blank" rel="noreferrer">Grok Bot 官方使用指南</a> 与 <a href="https://cursor.com/cn/docs/grok-bot/computers" target="_blank" rel="noreferrer">云电脑与应用连接说明</a>。</p><h2 id="案例一-spacexai-团队的-pr-巡检与多-bot-编排" tabindex="-1">案例一：SpaceXAI 团队的 PR 巡检与多 Bot 编排 <a class="header-anchor" href="#案例一-spacexai-团队的-pr-巡检与多-bot-编排" aria-label="Permalink to &quot;案例一：SpaceXAI 团队的 PR 巡检与多 Bot 编排&quot;">​</a></h2><p>SpaceXAI 的 Lingxi Li（@lingxi）带了 5 个研发 Bot 加 1 个流程 Bot，配 Cursor cloud agent 全天跑。</p><p>团队里的 @poteto 单月合入超 2,000 个 PR，Lingxi 自己也只花 3 周就搞定了 iOS v0。</p><p>5 个研发 Bot 隔离了上下文，各自盯一块代码，按任务调对应命令：</p><ul><li>Baltata 负责 iOS 与移动共享层，Craig 负责 Android。</li><li>Shaoruru 负责桌面端与 CI/CD，Quill 维护 Harness 工具链。</li><li>Hogan 专查底层基建与无归属 Bug。</li><li>视觉走 <code>/lingxi-design</code>，代码质量走 <code>/react-native-best-practices</code>，架构走 <code>/lingxi-review</code>。</li></ul><p>主管 Bot Jenny 不写代码，每天早 5 点逐个对齐手册。<strong>研发 Bot 一旦审查放水或没彻底验证就交付，Jenny 会抓出来做 RCA 并更新规则</strong>。</p><p>长会话容易把上下文撑爆，团队把状态放进 Notion 库，靠定时轮询跑完闭环：</p><ol><li><p><strong>半小时轮询</strong>：每 30 分钟扫一遍 open PR，核验 Bugbot 结果、CI 报错和 Git 冲突。</p><p>有问题调 Cursor 修复并切回 Working，全绿切为 Ready for Review；只有置信度极高且改动影响极小时才自动合入。<strong>单人并发调度量从 15 提到了 200 个以上</strong>。</p></li><li><p><strong>真机截图对齐</strong>：代码断言容易漏掉视觉显示问题，团队拿闲置 Mac mini 当私有 Worker 跑 iOS Simulator，<strong>靠多模态比对前后真实截图</strong>，视觉不对就直接打回。</p></li><li><p><strong>凌晨 3 点夜间审计</strong>：清理死代码缩包，排查依赖安全和 CI 耗时，补齐国际化，检查多端功能对等，汇总过去 24 小时 PR。</p></li></ol><blockquote><p>来源：<a href="https://x.com/KinGao476942/status/2096232745538334913" target="_blank" rel="noreferrer">工程师如何用好 Grok bot?</a><br> 作者：<a href="https://x.com/KinGao476942" target="_blank" rel="noreferrer">Kin @KinGao476942</a></p></blockquote><p><img src="`+s+'" alt="工程师如何用好 Grok bot?" loading="lazy" decoding="async"></p><p><img src="'+n+'" alt="工程师如何用好 Grok bot?" loading="lazy" decoding="async"></p><p><strong>别让单个 Bot 扛长会话</strong>。按业务拆角色，设专人复盘规则，把状态放到看板里做差异核对，省心很多。</p><ul><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/H576wlwF3i3si7kVUJZckeFfn3g" target="_blank" rel="noreferrer">《工程师如何用好 Grok bot?｜Kin》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/G2YNwaSvpixAhFkjL4xcVm0tn5d" target="_blank" rel="noreferrer">《Grok Bot for Engineering｜Lingxi Li》</a></li></ul><h2 id="案例二-研发工作拆解与-lauren-的九类清单" tabindex="-1">案例二：研发工作拆解与 Lauren 的九类清单 <a class="header-anchor" href="#案例二-研发工作拆解与-lauren-的九类清单" aria-label="Permalink to &quot;案例二：研发工作拆解与 Lauren 的九类清单&quot;">​</a></h2><h3 id="具体怎么做" tabindex="-1">具体怎么做 <a class="header-anchor" href="#具体怎么做" aria-label="Permalink to &quot;具体怎么做&quot;">​</a></h3><p>Lauren（@poteto）单月合并 2,500 个生产 PR，Jacob Gold（@jacobgold）日均近 250 个，两人把工程拆成九条线并行跑。</p><table tabindex="0"><thead><tr><th style="text-align:left;">风险级别</th><th style="text-align:left;">典型范围与规则</th><th style="text-align:left;">审查方式</th></tr></thead><tbody><tr><td style="text-align:left;">低至中</td><td style="text-align:left;">清理死代码、单测与类型修正</td><td style="text-align:left;">自动合入</td></tr><tr><td style="text-align:left;">高风险</td><td style="text-align:left;">核心业务、鉴权与数据迁移</td><td style="text-align:left;">强制人工审查</td></tr></tbody></table><p><strong>只要 Diff 超出原始提示词意图，系统立即推给人工拍板。</strong></p><h3 id="可以借鉴什么" tabindex="-1">可以借鉴什么 <a class="header-anchor" href="#可以借鉴什么" aria-label="Permalink to &quot;可以借鉴什么&quot;">​</a></h3><p>Mai Yang（@MaiYangAI）半年在 ContextEcho 产生 1,020 个提交，仅 18 次走 PR。<strong>单人项目破坏面极小，缺乏真实需求时硬造 PR 毫无价值。</strong></p><blockquote><p>来源：<a href="https://x.com/MaiYangAI/status/2108519046446727633" target="_blank" rel="noreferrer">一天几百个 PR 有什么意义？我照着 SpaceXAI 工程师 Lauren（@poteto）的九类清单，把自己的活拆了一遍</a><br> 作者：<a href="https://x.com/MaiYangAI" target="_blank" rel="noreferrer">Mai Yang @MaiYangAI</a> 先选 Bug 修复与规范重构两项，加上输入限制和验收标准。<strong>省下肉眼看代码的精力，转去抓方向定义、边界约束与测试。</strong></p></blockquote><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/VznKwUNQyi7RBJkih15cmjGhnSd" target="_blank" rel="noreferrer">《一天几百个 PR 有什么意义？我照着 SpaceXAI 工程师 Lauren（@poteto）的九类清单，把自己的活拆了一遍》</a></p><h2 id="案例三-24-7-仓库值班台-repo-ops-desk" tabindex="-1">案例三：24/7 仓库值班台（Repo Ops Desk） <a class="header-anchor" href="#案例三-24-7-仓库值班台-repo-ops-desk" aria-label="Permalink to &quot;案例三：24/7 仓库值班台（Repo Ops Desk）&quot;">​</a></h2><p><img src="'+u+`" alt="案例三：24/7 仓库值班台（Repo Ops Desk）" width="1600" height="1013" loading="lazy" decoding="async"></p><h3 id="谁在做与做了什么" tabindex="-1">谁在做与做了什么 <a class="header-anchor" href="#谁在做与做了什么" aria-label="Permalink to &quot;谁在做与做了什么&quot;">​</a></h3><p>独立开发者 Gipp 🦅（@gippp69）在维护多个开源项目与业务仓库时，设计了一套 24/7 仓库值班台。这套系统在底层结合并发子 Agent 监控异常，在顶层通过 Grok Bot 部署 6 个具名角色处理 Issue 与 CI 报错。</p><p>根据作者自述，个人手工通常只能盯 2 到 3 个仓库。而自动化值班台能同时监控多仓库的数百个改动点。</p><h3 id="具体怎么做-1" tabindex="-1">具体怎么做 <a class="header-anchor" href="#具体怎么做-1" aria-label="Permalink to &quot;具体怎么做&quot;">​</a></h3><details class="details custom-block"><summary>具体怎么做</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[GitHub 事件 / CI 报警]</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>    ┌───────────┐</span></span>
<span class="line"><span>    │Triage Bot │ ── 识别严重度与类别</span></span>
<span class="line"><span>    └─────┬─────┘</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>   ┌──────┴───────────────────────────┐</span></span>
<span class="line"><span>   ▼                                  ▼</span></span>
<span class="line"><span>[偶发测试 / 格式问题]             [业务逻辑缺陷 / CVE 安全问题]</span></span>
<span class="line"><span>   │                                  │</span></span>
<span class="line"><span>   ▼                                  ▼</span></span>
<span class="line"><span>┌─────────┐                      ┌─────────────────────────┐</span></span>
<span class="line"><span>│ Fix Bot │                      │ Dependency / Alert Bot  │</span></span>
<span class="line"><span>└────┬────┘                      └────────────┬────────────┘</span></span>
<span class="line"><span>     │                                        │</span></span>
<span class="line"><span>     ▼                                        ▼</span></span>
<span class="line"><span>[生成修复 Patch]                   [严重漏洞即时呼叫人类]</span></span>
<span class="line"><span>     │                                        │</span></span>
<span class="line"><span>     ▼                                        ▼</span></span>
<span class="line"><span>[提交 Draft PR (严禁合并)]           [其余汇总至次日晨报]</span></span></code></pre></div></details><ol><li><p><strong>部署 6 个专职 Bot</strong></p><ul><li>Triage Bot：按严重程度和类型归类 Issue。</li><li>Fix Bot：接管轻度 Bug，写补丁并提 Draft PR。</li><li>Test Bot：跑测试抓 Flaky test，记下失败上下文。</li><li>Dependency Bot：监控 CVE 漏洞与过期依赖。</li><li>Release Bot：按指令整理变更日志并打包。</li><li>Alert Bot：需人工介入时即时发通知。</li></ul></li><li><p><strong>按路由表锁定权限</strong></p></li></ol><table tabindex="0"><thead><tr><th style="text-align:left;">权限层级</th><th style="text-align:left;">监控范围</th><th style="text-align:left;">角色与动作</th></tr></thead><tbody><tr><td style="text-align:left;"><code>auto-fix</code></td><td style="text-align:left;">Flaky 测试、Lint 报错与格式</td><td style="text-align:left;">Fix Bot 提补丁</td></tr><tr><td style="text-align:left;"><code>triage</code></td><td style="text-align:left;">未归类复杂缺陷与需求</td><td style="text-align:left;">Triage Bot 转人工</td></tr><tr><td style="text-align:left;"><code>security</code></td><td style="text-align:left;">中高危 CVE 漏洞</td><td style="text-align:left;">Dependency 发现即转 Alert 告警</td></tr><tr><td style="text-align:left;"><code>release</code></td><td style="text-align:left;">版本变更与发布说明</td><td style="text-align:left;">Release Bot 听指令执行</td></tr></tbody></table><ol start="3"><li><strong>守住三条硬性红线</strong><ul><li>绝不碰业务逻辑：<code>auto-fix</code> 改动仅限失败测试文件本身或直接引用，严禁改核心代码。</li><li>绝不自动合并：Fix Bot 只开带 <code>auto-fix</code> 标签的 Draft PR，绝不自动 Merge。</li><li>灰度试跑一周：先在单个低风险边缘仓库跑一周，看采纳率（合并对比放弃数量），稳定后再推主仓。</li></ul></li></ol><h3 id="可以借鉴什么-1" tabindex="-1">可以借鉴什么 <a class="header-anchor" href="#可以借鉴什么-1" aria-label="Permalink to &quot;可以借鉴什么&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/gippp69/status/2095088203690570191" target="_blank" rel="noreferrer">How to Build a 24/7 Repo Ops Desk on Grok Bot + Kimi K3 (Complete Guide)</a><br> 作者：<a href="https://x.com/gippp69" target="_blank" rel="noreferrer">Gipp 🦅 @gippp69</a></p></blockquote><p><img src="`+e+'" alt="How to Build a 24/7 Repo Ops Desk on Grok Bot + Kimi K3 (Complete Guide)" loading="lazy" decoding="async"></p><p><img src="'+t+'" alt="How to Build a 24/7 Repo Ops Desk on Grok Bot + Kimi K3 (Complete Guide)" loading="lazy" decoding="async"><strong>值班台在深夜排查报错，不做决策</strong>。提示词和权限锁死「只开 Draft PR、绝不修改业务逻辑」，系统在无人看管下也能安全运行。</p><p>详细配置方案见 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/Lw4rwhHVNi3gECk0KH5cRl0znJh" target="_blank" rel="noreferrer">《How to Build a 24/7 Repo Ops Desk on Grok Bot + Kimi K3 (Complete Guide)｜Gipp 🦅》</a>。</p><h2 id="案例四-基于状态机与多-bot-协作的工程-harness" tabindex="-1">案例四：基于状态机与多 Bot 协作的工程 Harness <a class="header-anchor" href="#案例四-基于状态机与多-bot-协作的工程-harness" aria-label="Permalink to &quot;案例四：基于状态机与多 Bot 协作的工程 Harness&quot;">​</a></h2><p><img src="'+k+`" alt="案例四：基于状态机与多 Bot 协作的工程 Harness" width="1600" height="1013" loading="lazy" decoding="async"></p><h3 id="谁在做与做了什么-1" tabindex="-1">谁在做与做了什么 <a class="header-anchor" href="#谁在做与做了什么-1" aria-label="Permalink to &quot;谁在做与做了什么&quot;">​</a></h3><p>开发者 Mori（@0xjmori）、Morlex（@0xMorlex）与一人企业架构师 beamnxw 设计了标准化的研发协作流水线。他们通过在云端建立状态机合约、统一目录结构与六字段任务看板，实现了由 1 名总管协调 4 名专员的端到端修复管线。</p><p>整个系统把复杂的代码变更拆解为具备可核验凭据的状态流转。这一设计确保了各环节交接均有据可查。</p><h3 id="具体怎么做-2" tabindex="-1">具体怎么做 <a class="header-anchor" href="#具体怎么做-2" aria-label="Permalink to &quot;具体怎么做&quot;">​</a></h3><ol><li><strong>建立结构化工作区目录</strong> 在 Grok Bot 云电脑 <code>/workspace</code> 初始化工程，每个 Issue 进独立目录 <code>/workspace/devdesk/issues/&lt;issue-id&gt;/</code>。</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /workspace/devdesk/{queue,issues,reviews,approved,logs}</span></span></code></pre></div><p><strong>每个目录必须备齐 6 个标准文件</strong>。</p><ul><li><code>task.md</code>：原始输入与完成验收标准</li><li><code>status.json</code>：当前机器可读状态及负责人</li><li><code>evidence/</code>：存放失败日志、复现脚本与截图</li><li><code>implementation.md</code>：改动文件清单与最小实现方案</li><li><code>review.md</code>：独立审查结论</li><li><code>handoff.md</code>：交付人类的放行报告</li></ul><ol start="2"><li><strong>状态机转移契约</strong><strong>流水线按预定状态逐级推进，严禁跳步</strong>。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NEW ──&gt; TRIAGED ──&gt; REPRODUCED ──&gt; BUILDING ──&gt; TESTED ──&gt; REVIEWING ──&gt; REVIEW_PASSED ──&gt; DRAFT_PR_READY ──&gt; HUMAN_APPROVAL</span></span>
<span class="line"><span>                                                   ▲            │</span></span>
<span class="line"><span>                                                   └── FAILED ──┘</span></span></code></pre></div><ul><li><strong>Triage（<code>NEW</code> ──&gt; <code>REPRODUCED</code>）</strong>：必须提供稳定复现步骤和跑得通的失败用例。</li><li><strong>Builder（<code>BUILDING</code> ──&gt; <code>TESTED</code>）</strong>：派 Cursor agent 在新分支改代码，并保证原回归用例跑通。</li><li><strong>Reviewer（<code>REVIEWING</code> ──&gt; <code>REVIEW_PASSED</code>）</strong>：独立看 Diff 与日志给评级。<strong>一旦 FAIL 退回 <code>BUILDING</code> 重改，最多重试 2 轮</strong>。</li><li><strong>Release（<code>DRAFT_PR_READY</code> ──&gt; <code>HUMAN_APPROVAL</code>）</strong>：检查项全部通过后，向人类工程师提交带完整凭证的 Draft PR。</li></ul><ol start="3"><li><strong>动作可逆性分级</strong><strong>系统按动作是否可逆划定审批权限</strong>。</li></ol><table tabindex="0"><thead><tr><th style="text-align:left;">操作分类</th><th style="text-align:left;">权限策略</th><th style="text-align:left;">涵盖行为与操作范围</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>可逆动作</strong></td><td style="text-align:left;">自主执行</td><td style="text-align:left;">做代码分析，在本地分支编写补丁与跑单测，生成失败用例，提 Draft PR 并输出日志报告</td></tr><tr><td style="text-align:left;"><strong>不可逆动作</strong></td><td style="text-align:left;">停机等人审</td><td style="text-align:left;">向默认分支合并代码，部署上线，修改线上数据库，变更环境变量或密钥，调用收费外部服务</td></tr></tbody></table><ol start="4"><li><strong>看板与技能固化</strong> 看板字段固定为 <code>Task | Owner | Source | Status | Deliverable | Next action</code>。 任务状态严格限定在 <code>ready</code>、<code>working</code>、<code>blocked</code>、<code>awaiting approval</code> 与 <code>complete</code> 五种。 <strong>某类任务只要走通一次，就执行命令固化为私有 Skill</strong>，方便定时 Routine 重复调用。</li></ol><h3 id="可以借鉴什么-2" tabindex="-1">可以借鉴什么 <a class="header-anchor" href="#可以借鉴什么-2" aria-label="Permalink to &quot;可以借鉴什么&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/0xjmori/status/2109648700897116554" target="_blank" rel="noreferrer">Grok Bot + Opus 5.5: Build a 24/7 AI Engineering Team in 12 Steps</a><br> 作者：<a href="https://x.com/0xjmori" target="_blank" rel="noreferrer">Mori @0xjmori</a></p></blockquote><p><img src="`+l+'" alt="Grok Bot + Opus 5.5: Build a 24/7 AI Engineering Team in 12 Steps" loading="lazy" decoding="async"></p><p><img src="'+i+`" alt="Grok Bot + Opus 5.5: Build a 24/7 AI Engineering Team in 12 Steps" loading="lazy" decoding="async"></p><p>别让多 Agent 在非结构化群聊里随意接话。</p><ol><li><strong>上一步没存测试证据，下一步绝不启动</strong>。用磁盘目录和状态机卡住进展。</li><li><strong>区分动作可逆性</strong>，兼顾自动化速度的同时守住生产安全底线。</li></ol><p>具体实践参考 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/PxkpwzPFgi4NgCktD8NcfCpmnYf" target="_blank" rel="noreferrer">《Grok Bot + Opus 5.5: Build a 24/7 AI Engineering Team in 12 Steps》</a>、<a href="https://jcng5q8n0f3z.feishu.cn/wiki/A7BxwdM4QicxNZkmAWzcIt13nTh" target="_blank" rel="noreferrer">《Grok Bot + Opus 5.5: The Ultimate Agent Harness in 10 Steps｜Morlex》</a> 与 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/NYakw8hzLiScECkQ1b5ctWBmnvm" target="_blank" rel="noreferrer">《Grok Bot Engineering: Set Up a Harness for Your One-Person Company｜beamnxw ./》</a>。</p><h2 id="开箱即用-工程研发提示词库" tabindex="-1">开箱即用：工程研发提示词库 <a class="header-anchor" href="#开箱即用-工程研发提示词库" aria-label="Permalink to &quot;开箱即用：工程研发提示词库&quot;">​</a></h2><p>以下提示词均经过生产实践验证。你可以直接将其复制并配置到 Grok Bot 的 Bot Profile 或日常指令中：</p><h3 id="_1-架构总控章程-chief" tabindex="-1">1. 架构总控章程（Chief） <a class="header-anchor" href="#_1-架构总控章程-chief" aria-label="Permalink to &quot;1. 架构总控章程（Chief）&quot;">​</a></h3><p><strong>贴进主管 Bot 的 Profile Description</strong>，用来把控流程和记录状态。</p><details class="details custom-block"><summary>1. 架构总控章程（Chief）</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是 Chief，负责管理 /workspace/devdesk 工作区内的 AI 工程团队。</span></span>
<span class="line"><span>你的职责是将每一个接到的 Issue 推进至可供人工复审的 Draft PR 状态。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>工作原则：</span></span>
<span class="line"><span>1. 为每个处理阶段指派且仅指派一名专职 Bot。</span></span>
<span class="line"><span>2. 实时维护状态账本（status.json），防止任务重复分配。</span></span>
<span class="line"><span>3. 严格检查各阶段交付证据，绝不能仅凭下游 Bot 的口头回复判定任务完成。</span></span>
<span class="line"><span>4. 发生异常时记录阻塞点与失败尝试，连续失败两次立即终止重试。</span></span>
<span class="line"><span>5. 严禁亲自编写业务生产代码，严禁合并代码至默认分支，严禁触发生产部署。</span></span></code></pre></div></details><h3 id="_2-缺陷复现专员-triage" tabindex="-1">2. 缺陷复现专员（Triage） <a class="header-anchor" href="#_2-缺陷复现专员-triage" aria-label="Permalink to &quot;2. 缺陷复现专员（Triage）&quot;">​</a></h3><p>直接<strong>贴进 Triage Bot</strong>，用来挖缺陷、写失败用例。</p><details class="details custom-block"><summary>2. 缺陷复现专员（Triage）</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是 Triage 缺陷复现专员。</span></span>
<span class="line"><span>你的任务是调查收到的 GitHub Issue 并提供可稳定复现的证据。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>针对每个任务，请按顺序执行：</span></span>
<span class="line"><span>1. 阅读 Issue 描述与关联代码，明确系统预期行为。</span></span>
<span class="line"><span>2. 在云端测试环境中重现故障现象，抓取执行日志或错误堆栈。</span></span>
<span class="line"><span>3. 尽可能编写一个针对该故障的独立最小失败测试（Failing Test）。</span></span>
<span class="line"><span>4. 将重现步骤、测试命令与日志存入该 Issue 的 evidence/ 目录。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>红线要求：</span></span>
<span class="line"><span>- 证据不足时绝不推测原因。</span></span>
<span class="line"><span>- 严禁修改任何生产环境代码与系统配置。</span></span>
<span class="line"><span>- 交付内容必须包含：Issue 编号、复现步骤、失败测试运行结果、影响范围评估。</span></span></code></pre></div></details><h3 id="_3-编码专员-builder" tabindex="-1">3. 编码专员（Builder） <a class="header-anchor" href="#_3-编码专员-builder" aria-label="Permalink to &quot;3. 编码专员（Builder）&quot;">​</a></h3><p>把提示词贴进 <strong>Builder Bot</strong>，在隔离分支跑。</p><details class="details custom-block"><summary>3. 编码专员（Builder）</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是 Builder 编码专员。</span></span>
<span class="line"><span>你的任务是为已经由 Triage 成功复现的 Issue 提供最小安全修复代码。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>工作流程：</span></span>
<span class="line"><span>1. 完整阅读 Triage 提供的复现报告与失败测试。</span></span>
<span class="line"><span>2. 新建独立 Git 分支（格式：fix/&lt;issue-id&gt;），绝不在主分支修改。</span></span>
<span class="line"><span>3. 保持 Triage 编写的失败测试不变，针对性修改业务代码以消除该报错。</span></span>
<span class="line"><span>4. 运行相关测试套件，确认修改后原用例通过且无新增断言失败。</span></span>
<span class="line"><span>5. 提交代码并推送至远端，创建 Draft PR。</span></span>
<span class="line"><span>6. 输出变更文件清单、测试执行日志与潜在风险分析。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>红线要求：</span></span>
<span class="line"><span>- 严禁推送至默认主分支，严禁直接合并，严禁修改无关文件。</span></span>
<span class="line"><span>- 如果需要调用 Cursor cloud agent，必须在独立环境中派生，严禁多 Agent 并发写入同一文件。</span></span></code></pre></div></details><h3 id="_4-独立审查专员-reviewer" tabindex="-1">4. 独立审查专员（Reviewer） <a class="header-anchor" href="#_4-独立审查专员-reviewer" aria-label="Permalink to &quot;4. 独立审查专员（Reviewer）&quot;">​</a></h3><p>提示词粘进 Reviewer Bot，<strong>严格验收</strong>。</p><details class="details custom-block"><summary>4. 独立审查专员（Reviewer）</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是 Reviewer 独立审查专员。</span></span>
<span class="line"><span>你的职责是独立核验 Builder 提交的修改结果。你必须站在挑剔的角度排查潜在问题，绝不接受无凭据的口头总结。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>核查清单：</span></span>
<span class="line"><span>1. 修复方案是否确实解决了原始 Issue 反馈的问题？</span></span>
<span class="line"><span>2. 提供的回归测试是否确实在修复前失败、修复后通过？</span></span>
<span class="line"><span>3. 是否改动了与本任务无关的文件？</span></span>
<span class="line"><span>4. 是否存在未处理的边界场景、空指针或异常处理漏洞？</span></span>
<span class="line"><span>5. 汇报的测试结果是否有真实命令行输出日志支持？</span></span>
<span class="line"><span>6. 代码是否引入了新的安全隐患、性能退化或接口兼容性风险？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>判定输出（三选一）：</span></span>
<span class="line"><span>- PASS：符合质量要求，附带核实依据。</span></span>
<span class="line"><span>- FAIL：未达标，指出具体文件、行号、缺陷原因与修改要求。</span></span>
<span class="line"><span>- BLOCKED：证据缺失或需要上级审批权限。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>红线要求：严禁亲自修改任何业务实现代码。</span></span></code></pre></div></details><h3 id="_5-交付专员-release" tabindex="-1">5. 交付专员（Release） <a class="header-anchor" href="#_5-交付专员-release" aria-label="Permalink to &quot;5. 交付专员（Release）&quot;">​</a></h3><p><strong>把提示词贴进 Release Bot</strong>，用来汇总产物并交付：</p><details class="details custom-block"><summary>5. 交付专员（Release）</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是 Release 交付专员。</span></span>
<span class="line"><span>你只接收已达到以下条件的任务：</span></span>
<span class="line"><span>1. 存在有效的 Draft PR 链接。</span></span>
<span class="line"><span>2. 自动化检查全部通过，附带真实运行日志。</span></span>
<span class="line"><span>3. Reviewer 明确给出了 PASS 结论，无遗留未决缺陷。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>交付动作：</span></span>
<span class="line"><span>整理一份清晰的放行说明文件（handoff.md），包含：</span></span>
<span class="line"><span>- Issue 链接与 Draft PR 链接。</span></span>
<span class="line"><span>- 本次变更的核心内容说明。</span></span>
<span class="line"><span>- 执行的测试项及其控制台输出摘要。</span></span>
<span class="line"><span>- 明确标注等待人类审批的操作（如 Merge、线上配置生效等）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>红线要求：严禁自动合并 PR，严禁操作生产分支。</span></span></code></pre></div></details><h3 id="_6-夜间值守例行任务-engineering-night-shift-routine" tabindex="-1">6. 夜间值守例行任务（Engineering Night Shift Routine） <a class="header-anchor" href="#_6-夜间值守例行任务-engineering-night-shift-routine" aria-label="Permalink to &quot;6. 夜间值守例行任务（Engineering Night Shift Routine）&quot;">​</a></h3><p>在 Grok Bot 里配定时任务，<strong>执行主体选 Chief</strong>。</p><details class="details custom-block"><summary>6. 夜间值守例行任务（Engineering Night Shift Routine）</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>创建名为「Engineering Night Shift」的定时例行任务。</span></span>
<span class="line"><span>负责人：Chief</span></span>
<span class="line"><span>触发时间：工作日每晚 23:00（按配置的时区）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>工作流程：</span></span>
<span class="line"><span>1. 检索当前仓库中带有「agent-ready」标签的 GitHub Issue，单次最多提取 2 个。</span></span>
<span class="line"><span>2. 检查本地任务账本，跳过已在处理中的任务。</span></span>
<span class="line"><span>3. 调度 Triage、Builder、Reviewer 按预设流程流转，使用独立分支与 Cursor cloud agent。</span></span>
<span class="line"><span>4. 要求独立审查证据，最终仅产出 Draft PR。</span></span>
<span class="line"><span>5. 汇总生成一份晨间交接报告，列出：已完成的 Draft PR、阻塞的任务、失败的测试项、待审批事项。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>终止条件：</span></span>
<span class="line"><span>- 遇到未授权仓库或无权限文件。</span></span>
<span class="line"><span>- 缺陷无法稳定复现。</span></span>
<span class="line"><span>- Builder 修复尝试达到 2 次仍未通过审查。</span></span>
<span class="line"><span>- 改动涉及数据库迁移、认证安全或核心计费模块。</span></span></code></pre></div></details><h3 id="_7-可逆性人闸与安全红线指令" tabindex="-1">7. 可逆性人闸与安全红线指令 <a class="header-anchor" href="#_7-可逆性人闸与安全红线指令" aria-label="Permalink to &quot;7. 可逆性人闸与安全红线指令&quot;">​</a></h3><p><strong>直接贴到各 Bot 通用规则或 Profile Description 末尾</strong>。</p><details class="details custom-block"><summary>7. 可逆性人闸与安全红线指令</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>执行动作分级准则：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【允许自主执行（可逆操作）】</span></span>
<span class="line"><span>- 分析代码仓库、检索 Issue、编写复现测试。</span></span>
<span class="line"><span>- 在独立工作分支修改代码、执行本地测试构建。</span></span>
<span class="line"><span>- 编写审查报告、更新任务状态账本、开启 Draft PR。</span></span>
<span class="line"><span>遇到此类任务，自主完成并记录操作日志，无需等待确认。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【强制停机等待审批（不可逆或高危操作）】</span></span>
<span class="line"><span>- 向默认主干分支合并代码或推送更新。</span></span>
<span class="line"><span>- 执行任何生产环境部署操作。</span></span>
<span class="line"><span>- 涉及修改数据库表结构、数据迁移或删除数据。</span></span>
<span class="line"><span>- 变更系统认证、敏感密钥或外部扣费配置。</span></span>
<span class="line"><span>- 向公司外部人员发送通知或公开对外发布内容。</span></span>
<span class="line"><span>遇到此类动作，必须立即挂起任务，记录当前进展并等待人工授权。</span></span></code></pre></div></details><hr><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2><h3 id="模型自动匹配" tabindex="-1">模型自动匹配 <a class="header-anchor" href="#模型自动匹配" aria-label="Permalink to &quot;模型自动匹配&quot;">​</a></h3><p>后台会自动匹配 Claude Opus 5.5 等底层模型，无法手动挑。<strong>把流转条件写进 <code>status.json</code> 等结构化文件，靠硬脚本校验</strong>，别指望模型输出风格一直稳定。</p><h3 id="共享环境冲突" tabindex="-1">共享环境冲突 <a class="header-anchor" href="#共享环境冲突" aria-label="Permalink to &quot;共享环境冲突&quot;">​</a></h3><p>所有 Bot 共用云电脑的 <code>/workspace</code>。<strong>每个 Issue 必须用独立子目录与 Git 分支</strong>，改代码派生 Cursor cloud agent，严禁混用未提交的工作树。</p><h3 id="审查死循环与篡改测试" tabindex="-1">审查死循环与篡改测试 <a class="header-anchor" href="#审查死循环与篡改测试" aria-label="Permalink to &quot;审查死循环与篡改测试&quot;">​</a></h3><p>Builder 修复失败容易死循环，甚至会改测试断言骗绿灯。<strong>单个 Issue 重试严格限制在 2 轮以内</strong>，超限立刻转人工。Reviewer 必须比对测试用例的 Git Diff，改动断言直接判 FAIL。</p><h3 id="订阅额度与轮询" tabindex="-1">订阅额度与轮询 <a class="header-anchor" href="#订阅额度与轮询" aria-label="Permalink to &quot;订阅额度与轮询&quot;">​</a></h3><p>用量按 2026 年 10 月 12 日生效的 The X Subscription 执行，和 Grok、Cursor 共享周用量池，超额走 Cursor 计费。</p><p>别搞 5 分钟全量扫描，<strong>定时任务设成每天或夜间 1 次</strong>，触发尽量靠 <code>agent-ready</code> 标签。</p><table tabindex="0"><thead><tr><th style="text-align:left;">订阅方案</th><th style="text-align:left;">月费价格</th><th style="text-align:left;">额度倍数</th><th style="text-align:left;">是否包含 Grok Bot</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Plus</strong></td><td style="text-align:left;">-</td><td style="text-align:left;">-</td><td style="text-align:left;">不含 Bot</td></tr><tr><td style="text-align:left;"><strong>Premium</strong></td><td style="text-align:left;">$30 / 月</td><td style="text-align:left;">4x 额度</td><td style="text-align:left;">包含</td></tr><tr><td style="text-align:left;"><strong>Super</strong></td><td style="text-align:left;">$100 / 月</td><td style="text-align:left;">15x 额度</td><td style="text-align:left;">包含</td></tr><tr><td style="text-align:left;"><strong>Ultra</strong></td><td style="text-align:left;">$200 / 月</td><td style="text-align:left;">50x 额度</td><td style="text-align:left;">包含</td></tr></tbody></table><h3 id="分支保护与-draft-pr" tabindex="-1">分支保护与 Draft PR <a class="header-anchor" href="#分支保护与-draft-pr" aria-label="Permalink to &quot;分支保护与 Draft PR&quot;">​</a></h3><p><strong>Agent 产物只做 Draft PR，严禁自动合入主分支</strong>。GitHub 的 Branch Protection Rules 必须卡死三条硬性约束：</p><ul><li>禁止直接 Push 到 main 或 master 分支</li><li>至少一人人工审批（Approvals）</li><li>必须跑通原有 CI 流水线</li></ul><h3 id="敏感凭据防泄漏" tabindex="-1">敏感凭据防泄漏 <a class="header-anchor" href="#敏感凭据防泄漏" aria-label="Permalink to &quot;敏感凭据防泄漏&quot;">​</a></h3><p>对话内容会进模型上下文，<strong>严禁在提示词里输入密码、私钥或 API 密钥</strong>。访问私有系统走设置里的连接器，或者用 Agent Computer 的 Take Control 远程桌面手工登录。</p><h2 id="做完怎么验收" tabindex="-1">做完怎么验收 <a class="header-anchor" href="#做完怎么验收" aria-label="Permalink to &quot;做完怎么验收&quot;">​</a></h2><p><strong>切忌一上来就在生产核心项目全面铺开</strong>。</p><h3 id="单仓库单-bug-冷启动验收" tabindex="-1">单仓库单 Bug 冷启动验收 <a class="header-anchor" href="#单仓库单-bug-冷启动验收" aria-label="Permalink to &quot;单仓库单 Bug 冷启动验收&quot;">​</a></h3><ul><li>挑边缘库建 <code>/workspace/devdesk/</code>，选小 Bug 打上 <code>agent-ready</code>。</li><li>跑 Chief 流程，核验 Triage 在 <code>evidence/</code> 下存好复现日志与单测。</li><li>Builder 在独立分支改且不碰主干代码，Reviewer 给出行号与逻辑核对。</li><li><strong>确认最终只提 Draft PR</strong>，主分支无任何变更。</li></ul><h3 id="指标量化与补丁采纳率检验" tabindex="-1">指标量化与补丁采纳率检验 <a class="header-anchor" href="#指标量化与补丁采纳率检验" aria-label="Permalink to &quot;指标量化与补丁采纳率检验&quot;">​</a></h3><ul><li>采纳率<strong>低于 70% 暂停接入第二仓库</strong>，收紧提示词约束。</li><li>晨报须在 <strong>3 分钟内</strong>看清合格 PR、拦截与待定项，翻看几千字对话算未达标。</li><li>凌晨定时任务无触发休眠，超时自动中断，避免额度暴击。</li></ul><h3 id="安全红线与权限拦截实操演练" tabindex="-1">安全红线与权限拦截实操演练 <a class="header-anchor" href="#安全红线与权限拦截实操演练" aria-label="Permalink to &quot;安全红线与权限拦截实操演练&quot;">​</a></h3><ul><li>故意提修改表结构（Migration）或认证逻辑的 Issue，确认任务被拦截挂起。</li><li>让 Bot 执行 <code>git push origin main</code>，<strong>分支保护必须成功拦截</strong>。</li><li>涉及外部通信与配置变更，确认 Auto-review 开启 <strong>Ask first</strong>。</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><h3 id="官方文档与功能页面" tabindex="-1">官方文档与功能页面 <a class="header-anchor" href="#官方文档与功能页面" aria-label="Permalink to &quot;官方文档与功能页面&quot;">​</a></h3><ul><li><a href="https://cursor.com/cn/docs/grok-bot/work" target="_blank" rel="noreferrer">Grok Bot 官方使用指南</a></li><li><a href="https://cursor.com/cn/docs/grok-bot/computers" target="_blank" rel="noreferrer">云电脑与应用连接</a></li><li><a href="https://cursor.com/cn/help/grok-bot/models" target="_blank" rel="noreferrer">模型选择与路由说明</a></li><li><a href="https://cursor.com/cn/help/grok-bot/plans" target="_blank" rel="noreferrer">方案、计费与按需用量帮助</a></li><li><a href="https://cursor.com/cn/docs/grok-bot/settings" target="_blank" rel="noreferrer">设置与安全规范</a></li><li><a href="https://cursor.com/cn/docs/grok-bot/teams" target="_blank" rel="noreferrer">团队协作与 Team Bots 配置</a></li></ul><h3 id="社区实战案例原文" tabindex="-1">社区实战案例原文 <a class="header-anchor" href="#社区实战案例原文" aria-label="Permalink to &quot;社区实战案例原文&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/lingxi/status/2094493172516966781" target="_blank" rel="noreferrer">Grok Bot for Engineering</a><br> 作者：<a href="https://x.com/lingxi" target="_blank" rel="noreferrer">Lingxi Li @lingxi</a></p></blockquote><p><img src="`+r+'" alt="Grok Bot for Engineering" loading="lazy" decoding="async"></p><p><img src="'+p+'" alt="Grok Bot for Engineering" loading="lazy" decoding="async"></p><ul><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/H576wlwF3i3si7kVUJZckeFfn3g" target="_blank" rel="noreferrer">《工程师如何用好 Grok bot?｜Kin》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/G2YNwaSvpixAhFkjL4xcVm0tn5d" target="_blank" rel="noreferrer">《Grok Bot for Engineering｜Lingxi Li》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/VznKwUNQyi7RBJkih15cmjGhnSd" target="_blank" rel="noreferrer">《一天几百个 PR 有什么意义？我照着 SpaceXAI 工程师 Lauren（@poteto）的九类清单，把自己的活拆了一遍》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/Lw4rwhHVNi3gECk0KH5cRl0znJh" target="_blank" rel="noreferrer">《How to Build a 24/7 Repo Ops Desk on Grok Bot + Kimi K3 (Complete Guide)｜Gipp 🦅》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/PxkpwzPFgi4NgCktD8NcfCpmnYf" target="_blank" rel="noreferrer">《Grok Bot + Opus 5.5: Build a 24/7 AI Engineering Team in 12 Steps》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/A7BxwdM4QicxNZkmAWzcIt13nTh" target="_blank" rel="noreferrer">《Grok Bot + Opus 5.5: The Ultimate Agent Harness in 10 Steps｜Morlex》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/NYakw8hzLiScECkQ1b5ctWBmnvm" target="_blank" rel="noreferrer">《Grok Bot Engineering: Set Up a Harness for Your One-Person Company｜beamnxw ./》</a></li></ul>',132)])])}const w=o(f,[["render",b]]);export{R as __pageData,w as default};
